import Foundation
import Testing
@testable import PixlLibrary

/// The stage 3 golden vectors (`ekf`, `listseed`, `replay`, `learner`): the learner's update and forgetting, the seed of a
/// list's posterior sample and the control-session rule, the replay that trains the ranker with the gate's figures, and the
/// learner's saved state. Generated by the Android repo's `./gradlew :brain:generateGolden`, copied here unchanged. The
/// README beside the files says how each `fn` is replayed.
@Suite("Brain stage 3 golden vectors (brainMatchesAndroid)")
struct BrainStage3GoldenTests {
    typealias G = BrainGoldenTests
    typealias M2 = BrainStage2bM2GoldenTests
    typealias Value = BrainJson.Value

    static func model(_ v: Value) -> RankerModel {
        var model = Ranker.newModel(today: G.long(v, "anchorDay"))
        model.m = M2.doubles(v, "m")
        model.q = M2.doubles(v, "q")
        model.forgetDone = Int(G.int(v, "forgetDone"))
        model.updates = G.long(v, "updates")
        model.lastEventId = G.long(v, "lastEventId")
        model.resets = Int(G.int(v, "resets"))
        return model
    }

    static func writeModel(_ w: inout BrainJson.Writer, _ m: RankerModel) {
        w.beginArray("m")
        for i in 0..<Ranker.d { w.doubleItem(m.m[i]) }
        w.endArray()
        w.beginArray("q")
        for i in 0..<Ranker.d { w.doubleItem(m.q[i]) }
        w.endArray()
        w.long("anchorDay", m.anchorDay); w.int("forgetDone", m.forgetDone); w.long("updates", m.updates)
        w.long("lastEventId", m.lastEventId); w.int("resets", m.resets)
    }

    static func writeSummary(_ w: inout BrainJson.Writer, _ s: Gate.Summary) {
        w.int("plays", s.plays); w.int("playsTotal", s.playsTotal)
        w.double("llLearned", s.logLossLearned); w.double("llPrior", s.logLossPrior)
        w.double("accLearned", s.accLearned); w.double("accPrior", s.accPrior)
        if let v = s.accLearnedBefore { w.double("accLearnedBefore", v) } else { w.nullValue("accLearnedBefore") }
        if let v = s.accPriorBefore { w.double("accPriorBefore", v) } else { w.nullValue("accPriorBefore") }
    }

    // MARK: ekf.jsonl

    @Test func ekfMatchesAndroid() throws {
        var report = G.Report(file: "ekf.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("ekf.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "ekf":
                var model = Ranker.newModel(today: G.long(i, "day0"))
                var statuses: [Int32] = []
                for step in G.array(i, "steps") {
                    let s = step.arrayValue ?? []
                    var x = [Double](repeating: 0.0, count: Ranker.d)
                    x[0] = 1.0
                    for pair in s[5].arrayValue ?? [] {
                        let p = pair.arrayValue ?? []
                        x[Int(p[0].bareLong ?? 0)] = p[1].doubleValue ?? .nan
                    }
                    let status = Ranker.applyEvent(&model, x, r: s[3].doubleValue ?? .nan, c: s[4].doubleValue ?? .nan,
                                                   bias: s[2].doubleValue ?? .nan, day: s[1].longValue ?? 0,
                                                   eventId: s[0].longValue ?? 0)
                    statuses.append(Int32(status))
                }
                report.record(c, c.matches {
                    $0.ints("status", statuses); Self.writeModel(&$0, model)
                    $0.long("mHash", M2.hashDoubles(model.m)); $0.long("qHash", M2.hashDoubles(model.q))
                })
            case "forget":
                var model = Self.model(i)
                var runs: [Int32] = []
                for day in G.longs(i, "days") { runs.append(Int32(Ranker.forget(&model, today: day))) }
                report.record(c, c.matches { $0.ints("runs", runs); Self.writeModel(&$0, model) })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 10)
        #expect(counts["ekf"] == 6)
        #expect(counts["forget"] == 4)
    }

    // MARK: listseed.jsonl

    @Test func listSeedAndControlMatchAndroid() throws {
        var report = G.Report(file: "listseed.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("listseed.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "listSeed":
                let seed = Ranker.listSeed(salt: G.long(i, "salt"), listId: G.string(i, "listId"), localDay: G.long(i, "localDay"))
                var rng = BrainHash.Rng(seed: UInt64(bitPattern: seed))
                let gauss = rng.gaussian12()
                report.record(c, c.matches { $0.long("seed", seed); $0.double("firstGaussian", gauss) })
            case "control":
                let control = Ranker.isControlSession(G.long(i, "sessionId"))
                report.record(c, c.matches { $0.bool("control", control) })
            case "sample":
                let model = Self.model(i)
                var rng = BrainHash.Rng(seed: UInt64(bitPattern: G.long(i, "seed")))
                let w = Ranker.sampleWeights(model, &rng)
                report.record(c, c.matches {
                    $0.long("hash", M2.hashDoubles(w)); $0.double("w0", w[0]); $0.double("w1", w[1]); $0.double("w2", w[2])
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 90)
        #expect(counts["listSeed"] == 27)
        #expect(counts["control"] == 64)
        #expect(counts["sample"] == 3)
    }

    // MARK: replay.jsonl

    @Test func learnReplayMatchesAndroid() throws {
        var report = G.Report(file: "replay.jsonl")
        for c in try G.cases("replay.jsonl") {
            let i = c.input
            guard c.fn == "learnReplay" else {
                report.record(c, false)
                continue
            }
            let nowMs = G.long(i, "nowMs")
            let result = LearnReplay.run(G.events(i, "events"), facts: .empty, nowMs: nowMs, likedRids: Set(G.longs(i, "liked")),
                                         tzNowMin: G.int(i, "tzNowMin"))
            let summary = Gate.summarize(result.predictions, nowMs: nowMs)
            report.record(c, c.matches {
                Self.writeModel(&$0, result.model)
                $0.int("events", result.events); $0.long("lastEventId", result.lastEventId)
                $0.long("snapshotHash", BrainHash.id(BrainHash.fnv1a64(Snapshot.encode(result.state))))
                $0.int("graded", result.predictions.size)
                $0.long("learnedHash", M2.hashDoubles(result.predictions.learned))
                $0.long("priorHash", M2.hashDoubles(result.predictions.prior))
                Self.writeSummary(&$0, summary)
            })
        }
        report.verify(atLeast: 3)
    }

    // MARK: learner.jsonl

    @Test func gateCodecAndLogLossMatchAndroid() throws {
        var report = G.Report(file: "learner.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("learner.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "gate":
                let plays = Int(G.int(i, "plays"))
                let summary = Gate.Summary(plays: plays, playsTotal: plays, logLossLearned: G.double(i, "llLearned"),
                                           logLossPrior: G.double(i, "llPrior"), accLearned: 0.6, accPrior: 0.55,
                                           accLearnedBefore: nil, accPriorBefore: nil)
                let prev = Gate.State(useLearned: G.bool(i, "useLearned"), winStreak: Int(G.int(i, "winStreak")),
                                      atMs: G.long(i, "atMs"))
                let next = Gate.decide(prev, summary, nowMs: G.long(i, "nowMs"))
                report.record(c, c.matches {
                    $0.bool("useLearned", next.useLearned); $0.int("winStreak", next.winStreak); $0.long("atMs", next.atMs)
                })
            case "logLoss":
                let p = M2.doubles(i, "p")
                let y = G.array(i, "y").map { ($0.bareLong ?? 0) == 1 }
                let thr = [Double](repeating: 0.5, count: p.count)
                let ll = Gate.logLoss(p, y, from: 0, to: p.count)
                let acc = Gate.accuracy(p, thr, y, from: 0, to: p.count)
                report.record(c, c.matches { $0.double("logLoss", ll); $0.double("accuracy", acc) })
            case "codec":
                let model = Self.model(i)
                let useLearned = G.bool(i, "useLearned")
                // The case's own summary: present for the second case only (a gate that is on).
                let summary: Gate.Summary? = useLearned
                    ? Gate.Summary(plays: 900, playsTotal: 1200, logLossLearned: 0.51, logLossPrior: 0.55, accLearned: 0.7,
                                   accPrior: 0.66, accLearnedBefore: 0.68, accPriorBefore: 0.65) : nil
                let saved = LearnerCodec.Saved(model: model,
                                               gate: Gate.State(useLearned: useLearned, winStreak: useLearned ? 2 : 1,
                                                                atMs: 1_700_000_000_000),
                                               learnVersion: LearnReplay.version, summary: summary,
                                               rebuiltAtMs: 1_700_000_100_000)
                let text = LearnerCodec.encode(saved)
                let back = LearnerCodec.decode(text)
                report.record(c, c.matches {
                    $0.string("text", text)
                    $0.bool("readsBack", back != nil && LearnerCodec.encode(back!) == text)
                })
            case "codecBad":
                report.record(c, c.matches { $0.bool("accepted", LearnerCodec.decode(G.string(i, "text")) != nil) })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 50)
        #expect(counts["gate"] == 40)
        #expect(counts["logLoss"] == 6)
        #expect(counts["codec"] == 2)
        #expect(counts["codecBad"] == 4)
    }

    @Test func stage3FilesAreInTheManifest() throws {
        let manifest = String(decoding: try G.fixtureData("MANIFEST.sha256"), as: UTF8.self)
        for name in ["ekf.jsonl", "listseed.jsonl", "replay.jsonl", "learner.jsonl"] {
            #expect(manifest.contains("  \(name)"), "\(name) is not in MANIFEST.sha256")
        }
    }
}
